<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { AlertCircle, BookOpen, CheckCircle2, ChevronDown, Eye, FileText, FolderPlus, LoaderCircle, Pencil, Plus, RotateCw, Trash2, Upload, X } from 'lucide-vue-next'
import RagAuthGate from '../components/RagAuthGate.vue'
import { authState, clearCredentials, ragRequest } from '../rag/api'

type KB={id:string;name:string;course_name:string;document_count:number;created_at:string}
type Doc={id:string;knowledge_base_id:string;file_name:string;file_type:string;file_size:number;status:string;error_message:string;chunk_count:number;created_at:string}
type Preview={document_id:string;document_name:string;page:number|null;page_end?:number|null;section_title?:string;text:string;highlight?:string}
const authenticated=ref(false);const validatingAuth=ref(!!authState.token);const bases=ref<KB[]>([]);const selected=ref('');const docs=ref<Doc[]>([]);const loading=ref(false);const busy=ref(false);const error=ref('');const notice=ref('');const kbName=ref('');const courseName=ref('');const showCreate=ref(false);const nameInput=ref<HTMLInputElement>();const fileInput=ref<HTMLInputElement>();const preview=ref<Preview|null>(null);const previewBusy=ref(false);const page=ref(1);let pollTimer:number|undefined
const current=computed(()=>bases.value.find(k=>k.id===selected.value));const processing=computed(()=>docs.value.some(doc=>['UPLOADED','PARSING','CHUNKING','EMBEDDING','INDEXING'].includes(doc.status)))
function authDone(){authenticated.value=true;void loadBases()}
function logout(){clearCredentials();authenticated.value=false;bases.value=[];docs.value=[]}
function expireAuth(){logout();error.value='登录状态已过期，请重新登录'}
function explain(e:unknown){error.value=e instanceof Error?e.message:'服务请求失败'}
async function loadBases(){try{bases.value=await ragRequest<KB[]>('/knowledge-bases');if(!selected.value||!bases.value.some(k=>k.id===selected.value))selected.value=bases.value[0]?.id||''}catch(e){explain(e)}}
async function loadDocs(){if(!selected.value){docs.value=[];return}loading.value=true;try{docs.value=await ragRequest<Doc[]>(`/knowledge-bases/${selected.value}/documents`);await loadBases()}catch(e){explain(e)}finally{loading.value=false}}
async function openCreate(){showCreate.value=true;error.value='';notice.value='';await nextTick();nameInput.value?.focus()}
async function createBase(){const name=kbName.value.trim();if(!name){error.value='请填写知识库名称后再创建';nameInput.value?.focus();return}error.value='';notice.value='';busy.value=true;try{const result=await ragRequest<KB>('/knowledge-bases',{method:'POST',body:JSON.stringify({name,course_name:courseName.value.trim()})});bases.value.unshift(result);selected.value=result.id;kbName.value='';courseName.value='';showCreate.value=false;notice.value='知识库已创建'}catch(e){explain(e)}finally{busy.value=false}}
async function renameBase(){if(!current.value)return;const name=window.prompt('修改知识库名称',current.value.name);if(!name?.trim())return;try{await ragRequest(`/knowledge-bases/${current.value.id}`,{method:'PATCH',body:JSON.stringify({name:name.trim(),course_name:current.value.course_name})});await loadBases()}catch(e){explain(e)}}
async function deleteBase(){if(!current.value||!window.confirm(`删除知识库“${current.value.name}”及其中所有文档、索引和对话？此操作不可撤销。`))return;try{await ragRequest(`/knowledge-bases/${current.value.id}`,{method:'DELETE'});bases.value=bases.value.filter(k=>k.id!==selected.value);selected.value=bases.value[0]?.id||'';await loadDocs();notice.value='知识库及其数据已删除'}catch(e){explain(e)}}
function chooseFiles(){fileInput.value?.click()}
async function uploadFiles(event:Event){const target=event.target as HTMLInputElement;const files=Array.from(target.files||[]);target.value='';if(!selected.value||!files.length)return;busy.value=true;error.value='';for(const file of files){const body=new FormData();body.append('file',file);try{const item=await ragRequest<Doc>(`/knowledge-bases/${selected.value}/documents`,{method:'POST',body});docs.value.unshift(item);notice.value=`${file.name} 已保存，正在真实解析并建立索引`}catch(e){error.value=`${file.name}：${e instanceof Error?e.message:'上传失败'}`}}busy.value=false;await loadDocs()}
async function reindex(doc:Doc){try{const result=await ragRequest<Doc>(`/documents/${doc.id}/reindex`,{method:'POST'});Object.assign(doc,result);notice.value=`已开始重建 ${doc.file_name} 的索引`;void loadDocs()}catch(e){explain(e)}}
async function removeDoc(doc:Doc){if(!window.confirm(`删除“${doc.file_name}”及其向量索引？`))return;try{await ragRequest(`/documents/${doc.id}`,{method:'DELETE'});docs.value=docs.value.filter(item=>item.id!==doc.id);notice.value='文档与向量索引已删除';await loadBases()}catch(e){explain(e)}}
async function openPreview(doc:Doc){preview.value=null;previewBusy.value=true;page.value=1;try{preview.value=await ragRequest<Preview>(`/documents/${doc.id}/preview`)}catch(e){explain(e)}finally{previewBusy.value=false}}
async function loadPage(){if(!preview.value)return;previewBusy.value=true;try{preview.value=await ragRequest<Preview>(`/documents/${preview.value.document_id}/preview?page=${Math.max(1,page.value)}`)}catch(e){explain(e)}finally{previewBusy.value=false}}
function statusLabel(status:string){return ({UPLOADED:'已上传',PARSING:'解析中',CHUNKING:'分块中',EMBEDDING:'向量化中',INDEXING:'写入向量库',READY:'已就绪',FAILED:'处理失败'} as Record<string,string>)[status]||status}
function statusClass(status:string){return status==='READY'?'ready':status==='FAILED'?'failed':['UPLOADED','PARSING','CHUNKING','EMBEDDING','INDEXING'].includes(status)?'processing':'uploaded'}
function size(bytes:number){return bytes<1024*1024?`${Math.max(1,Math.round(bytes/1024))} KB`:`${(bytes/1024/1024).toFixed(1)} MB`}
watch(selected,()=>{void loadDocs()})
onMounted(async()=>{window.addEventListener('studypath:auth-expired',expireAuth);if(authState.token){try{await ragRequest('/auth/me');authenticated.value=true;await loadBases()}catch{clearCredentials()}finally{validatingAuth.value=false}}else validatingAuth.value=false;pollTimer=window.setInterval(()=>{if(processing.value)void loadDocs()},1800)})
onBeforeUnmount(()=>{window.clearInterval(pollTimer);window.removeEventListener('studypath:auth-expired',expireAuth)})
</script>

<template>
  <div v-if="validatingAuth" class="rag-auth-wrap"><div class="rag-library-loading"><LoaderCircle class="spin"/>正在验证登录状态…</div></div>
  <div v-else-if="!authenticated" class="rag-auth-wrap"><RagAuthGate @authenticated="authDone"/></div>
  <section v-else class="rag-library-page">
    <header class="rag-library-heading"><div><span class="rag-eyebrow">YOUR COURSE MATERIALS</span><h1>学习资料库</h1><p>文档会在后端完成解析、分块、Embedding 与向量索引；只有“已就绪”的资料可用于问答。</p></div><button type="button" class="rag-button primary" @click="showCreate ? showCreate=false : openCreate()"><FolderPlus :size="16"/>{{showCreate?'收起创建表单':'新建知识库'}}</button></header>
    <div class="rag-cloud-notice"><AlertCircle :size="16"/><span>资料存储在本地后端账号空间。提问时检索片段会发送给你配置的大模型服务；请勿上传未获授权的敏感资料。</span></div>
    <form v-if="showCreate" class="rag-create-base" @submit.prevent="createBase"><label>知识库名称 <span class="rag-required">必填</span><input ref="nameInput" v-model="kbName" maxlength="120" placeholder="例如：操作系统原理" :aria-invalid="!!error" :aria-describedby="error ? 'kb-create-hint' : undefined" @input="error=''"/></label><label>所属课程（可选）<input v-model="courseName" maxlength="120" placeholder="例如：计算机科学"/></label><button type="submit" class="rag-button primary" :disabled="busy"><LoaderCircle v-if="busy" :size="14" class="spin"/><Plus v-else :size="14"/>{{busy?'正在创建…':'创建知识库'}}</button><button type="button" class="rag-icon-button" aria-label="关闭创建表单" @click="showCreate=false;error=''"><X :size="16"/></button></form>
    <div v-if="error" id="kb-create-hint" class="rag-library-error" role="alert"><AlertCircle :size="15"/>{{error}}<button type="button" aria-label="关闭错误提示" @click="error=''"><X :size="14"/></button></div><div v-if="notice" class="rag-library-notice" role="status"><CheckCircle2 :size="15"/>{{notice}}<button type="button" aria-label="关闭提示" @click="notice=''"><X :size="14"/></button></div>
    <div class="rag-library-layout"><aside class="rag-kb-rail"><div class="rag-list-label">我的知识库 <span>{{bases.length}}</span></div><button v-for="kb in bases" :key="kb.id" class="rag-kb-row" :class="{active:selected===kb.id}" @click="selected=kb.id"><BookOpen :size="16"/><span><b>{{kb.name}}</b><small>{{kb.course_name||'未关联课程'}} · {{kb.document_count}} 份资料</small></span><ChevronDown :size="14"/></button><div v-if="!bases.length" class="rag-kb-empty">创建知识库后即可上传第一份课程资料。</div><div v-if="current" class="rag-kb-actions"><button @click="renameBase"><Pencil :size="13"/>重命名</button><button @click="deleteBase"><Trash2 :size="13"/>删除知识库</button></div></aside>
      <main class="rag-library-main"><template v-if="current"><div class="rag-material-toolbar"><div><span class="rag-eyebrow">{{current.course_name||'PERSONAL LIBRARY'}}</span><h2>{{current.name}}</h2><p>{{docs.length}} 份资料 · 只对当前账号开放</p></div><button class="rag-button primary" :disabled="busy" @click="chooseFiles"><Upload :size="15"/>上传资料</button><input ref="fileInput" type="file" accept=".pdf,.docx,.txt,.md" multiple hidden @change="uploadFiles"/></div>
          <div class="rag-upload-drop" @click="chooseFiles"><div><span class="rag-upload-icon"><Upload :size="18"/></span><b>拖入或选择课程资料</b><p>支持 PDF、DOCX、TXT、Markdown · 单文件最大 20 MB</p></div><button class="rag-button subtle" :disabled="busy">{{busy?'上传中…':'浏览文件'}}</button></div>
          <div class="rag-docs-heading"><div><h3>文档与索引</h3><span>后端状态会自动刷新</span></div><button class="rag-icon-button" title="刷新" @click="loadDocs"><RotateCw :size="15"/></button></div>
          <div v-if="loading&&!docs.length" class="rag-library-loading"><LoaderCircle class="spin"/>读取文档列表…</div>
          <div v-else-if="!docs.length" class="rag-library-empty"><FileText :size="23"/><b>这个知识库还没有文档</b><span>上传课程材料后，系统会生成真实向量索引。</span></div>
          <div v-else class="rag-document-list"><article v-for="doc in docs" :key="doc.id" class="rag-document-row"><div class="rag-doc-icon" :class="doc.file_type.toLowerCase()">{{doc.file_type}}</div><div class="rag-doc-main"><div class="rag-doc-name">{{doc.file_name}}<small>{{size(doc.file_size)}}</small></div><div class="rag-doc-meta"><span>{{doc.chunk_count}} 个文本块</span><span>·</span><span>{{new Date(doc.created_at).toLocaleDateString('zh-CN')}}</span><span v-if="doc.status==='READY'">· 已写入向量库</span></div><p v-if="doc.error_message" class="rag-doc-error">{{doc.error_message}}</p></div><span class="rag-status-pill" :class="statusClass(doc.status)"><LoaderCircle v-if="statusClass(doc.status)==='processing'" :size="12" class="spin"/><CheckCircle2 v-else-if="doc.status==='READY'" :size="12"/><AlertCircle v-else-if="doc.status==='FAILED'" :size="12"/>{{statusLabel(doc.status)}}</span><div class="rag-doc-actions"><button v-if="doc.status==='READY'" title="预览原文" @click="openPreview(doc)"><Eye :size="15"/></button><button v-if="doc.status==='FAILED'" title="重建索引" @click="reindex(doc)"><RotateCw :size="15"/></button><button title="删除文档" @click="removeDoc(doc)"><Trash2 :size="15"/></button></div></article></div>
        </template><div v-else class="rag-library-empty"><FolderPlus :size="25"/><b>先创建一个知识库</b><span>按课程或主题整理资料，再让答疑助手检索其中的原文。</span><button type="button" class="rag-button primary" @click="openCreate"><Plus :size="14"/>新建知识库</button></div></main></div>
    <div v-if="preview||previewBusy" class="rag-modal-backdrop" @click.self="preview=null"><section class="rag-preview-modal"><header><div><span class="rag-eyebrow">文档预览</span><h3>{{preview?.document_name||'正在读取'}}</h3><small>{{preview?.page?`第 ${preview.page} 页原文`: '解析后的文本'}}</small></div><button class="rag-icon-button" @click="preview=null"><X :size="17"/></button></header><div v-if="preview?.document_name && preview.document_name.toLowerCase().endsWith('.pdf')" class="rag-page-controls"><button class="rag-button subtle" @click="page=Math.max(1,page-1);loadPage()">上一页</button><label>页码 <input v-model.number="page" type="number" min="1" @change="loadPage"/></label><button class="rag-button subtle" @click="page++;loadPage()">下一页</button></div><div v-if="previewBusy" class="rag-preview-loading"><LoaderCircle class="spin"/>正在读取原文…</div><div v-else class="rag-preview-text"><div v-if="preview?.highlight" class="rag-original-quote"><b>检索到的原文片段</b><blockquote>{{preview.highlight}}</blockquote></div><pre>{{preview?.text}}</pre><p class="rag-muted">{{preview?.page?'页码来自原始 PDF 提取；文本定位来自真实页面内容。':'精确版面定位暂不可用，当前显示后端提取的文档文本。'}}</p></div></section></div>
  </section>
</template>

<style>
.rag-library-page{color:#302c3f}.rag-library-heading{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin:2px 2px 17px}.rag-library-heading h1{font-size:22px;margin:5px 0;letter-spacing:-.03em}.rag-library-heading p{font-size:11px;color:#9690a2;margin:0;line-height:1.6}.rag-cloud-notice{display:flex;align-items:flex-start;gap:9px;padding:11px 13px;border:1px solid #eee8fb;border-radius:10px;background:#faf8ff;color:#786a9a;font-size:10px;line-height:1.6;margin-bottom:16px}.rag-cloud-notice svg{flex:none;color:#9678db}.rag-create-base{display:flex;align-items:flex-end;gap:12px;padding:15px;margin:0 0 15px;border:1px solid #ece7f5;background:white;border-radius:13px}.rag-create-base label{display:grid;gap:6px;flex:1;color:#7f788e;font-size:10px}.rag-required{color:#b34b5c;font-size:9px}.rag-create-base input[aria-invalid="true"]{border-color:#c45c68;box-shadow:0 0 0 3px #c45c6818}.rag-create-base input{height:37px;border:1px solid #e8e4ed;border-radius:8px;padding:0 10px;font:inherit;font-size:11px;outline:0}.rag-create-base input:focus{border-color:#a38be3}.rag-library-layout{display:grid;grid-template-columns:235px minmax(0,1fr);gap:14px;align-items:start}.rag-kb-rail,.rag-library-main{background:white;border:1px solid #ece9f2;border-radius:15px;box-shadow:0 4px 18px #32245c08}.rag-kb-rail{padding:13px;min-height:300px}.rag-list-label{display:flex;justify-content:space-between;padding:4px 5px 11px;color:#8c8599;font-size:10px}.rag-list-label span{color:#9b8bbf}.rag-kb-row{width:100%;display:flex;align-items:center;gap:9px;padding:10px 8px;border:0;background:transparent;color:#80768e;border-radius:9px;text-align:left;cursor:pointer}.rag-kb-row.active,.rag-kb-row:hover{color:#7654ce;background:#f6f2ff}.rag-kb-row>span{flex:1;min-width:0}.rag-kb-row b,.rag-kb-row small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.rag-kb-row b{font-size:11px;font-weight:600}.rag-kb-row small{font-size:9px;color:#a09aab;margin-top:4px}.rag-kb-empty{padding:12px 5px;color:#a39cac;font-size:10px;line-height:1.7}.rag-kb-actions{display:flex;gap:6px;margin-top:14px;padding-top:10px;border-top:1px solid #f0edf4}.rag-kb-actions button{display:flex;align-items:center;gap:4px;border:0;background:none;color:#8d8799;font:inherit;font-size:9px;cursor:pointer}.rag-kb-actions button:last-child{color:#b95c68}.rag-library-main{padding:19px;min-height:420px}.rag-material-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:14px}.rag-material-toolbar h2{font-size:16px;margin:4px 0}.rag-material-toolbar p{color:#9b95a6;font-size:10px;margin:0}.rag-upload-drop{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:17px 18px;border:1px dashed #cfc5e7;border-radius:12px;background:linear-gradient(110deg,#fcfbff,#faf8ff);cursor:pointer}.rag-upload-drop>div{display:grid;grid-template-columns:34px auto;column-gap:10px;align-items:center}.rag-upload-icon{grid-row:span 2;width:34px;height:34px;display:grid;place-items:center;border-radius:10px;background:#efe9ff;color:#805fd2}.rag-upload-drop b{font-size:11px;color:#514a64}.rag-upload-drop p{font-size:9px;color:#9b95a5;margin:4px 0 0}.rag-library-notice,.rag-library-error{display:flex;align-items:center;gap:7px;margin-top:12px;padding:9px 11px;border-radius:8px;background:#f0fbf6;color:#468c73;font-size:10px}.rag-library-notice button,.rag-library-error button{margin-left:auto;border:0;background:none;color:inherit;cursor:pointer}.rag-library-error{background:#fff1f1;color:#af4d59}.rag-docs-heading{display:flex;align-items:center;justify-content:space-between;margin:22px 0 9px}.rag-docs-heading h3{font-size:12px;margin:0}.rag-docs-heading span{display:block;color:#a19bab;font-size:9px;margin-top:4px}.rag-library-loading,.rag-library-empty{display:grid;place-items:center;gap:8px;padding:50px 16px;color:#a39cad;text-align:center;font-size:10px}.rag-library-empty>b{font-size:12px;color:#696276}.rag-library-empty>span{line-height:1.6}.rag-library-empty>.rag-button{margin-top:7px}.rag-document-list{display:flex;flex-direction:column}.rag-document-row{display:flex;align-items:center;gap:11px;padding:12px 5px;border-top:1px solid #f1eef4}.rag-doc-icon{flex:none;width:36px;height:40px;display:grid;place-items:center;border-radius:8px;background:#f5efff;color:#835eda;font-size:8px;font-weight:700}.rag-doc-icon.pdf{background:#fff0f0;color:#ca5966}.rag-doc-icon.docx{background:#eef4ff;color:#5078c5}.rag-doc-icon.md,.rag-doc-icon.txt{background:#f0f8f5;color:#54a184}.rag-doc-main{flex:1;min-width:0}.rag-doc-name{font-size:11px;font-weight:600;color:#514b60;display:flex;align-items:center;gap:8px;min-width:0}.rag-doc-name:first-line{overflow-wrap:anywhere}.rag-doc-name small{flex:none;color:#a39dad;font-size:9px;font-weight:400}.rag-doc-meta{display:flex;gap:5px;margin-top:5px;color:#a09aaa;font-size:9px}.rag-doc-error{font-size:9px;color:#bc5860;margin:6px 0 0;line-height:1.5;overflow-wrap:anywhere}.rag-status-pill{flex:none;display:flex;align-items:center;gap:5px;padding:5px 7px;border-radius:20px;font-size:9px}.rag-status-pill.ready{color:#498e74;background:#edf8f2}.rag-status-pill.failed{color:#bd5864;background:#fff1f1}.rag-status-pill.processing{color:#8b6bcf;background:#f4efff}.rag-status-pill.uploaded{color:#827b90;background:#f3f1f6}.rag-doc-actions{display:flex;gap:3px}.rag-doc-actions button{display:grid;place-items:center;width:29px;height:29px;border:0;border-radius:7px;background:transparent;color:#9992a3;cursor:pointer}.rag-doc-actions button:hover{background:#f4f0fb;color:#7251ce}.rag-page-controls{display:flex;align-items:center;gap:8px;padding:10px 23px;border-bottom:1px solid #f0edf3}.rag-page-controls label{font-size:10px;color:#8d8798}.rag-page-controls input{width:65px;padding:7px;border:1px solid #eae6ef;border-radius:6px;font:inherit}.rag-library-page .rag-modal-backdrop{z-index:35}
@media(max-width:980px){.rag-library-layout{grid-template-columns:190px minmax(0,1fr)}}
@media(max-width:720px){.rag-library-layout{grid-template-columns:1fr}.rag-kb-rail{min-height:auto}.rag-kb-actions{margin-top:8px}.rag-library-heading{align-items:flex-start}.rag-library-heading h1{font-size:19px}.rag-library-main{padding:14px}.rag-doc-name{display:block;line-height:1.5}.rag-doc-name small{display:block}.rag-status-pill{font-size:8px;padding:4px 5px}.rag-doc-actions button{width:25px}.rag-create-base{flex-wrap:wrap}.rag-create-base label{min-width:150px}.rag-upload-drop{padding:13px}.rag-upload-drop p{max-width:220px}}
</style>
